INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',282,'{"_type":"chat:Message","id":"8641420749:737","threadId":"telegram:8641420749","text":"I stopped my strava recording today. Here are the 2 .fit files of the recordings I made, and a gpx of the missing piece. The missing piece was downhill, so estimate the HR based on the track and elevation, and add it to the missing part, then merge the 3 files into one .fit file. Then I’ll upload it to Strava.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I stopped my strava recording today. Here are the 2 .fit files of the recordings I made, and a gpx of the missing piece. The missing piece was downhill, so estimate the HR based on the track and elevation, and add it to the missing part, then merge the 3 files into one .fit file. Then I’ll upload it to Strava.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":312,"offset":311}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":312,"offset":311}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":312,"offset":311}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-20T15:54:31.000Z","edited":false},"attachments":[],"isMention":false}',1785167671635);
