INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',354,'{"_type":"chat:Message","id":"8641420749:873","threadId":"telegram:8641420749","text":"Je reste jusqu’au dimanche 9 donc dispo pour pedaler vendredi 7 et samedi 8. Surtout prévois que les 10 jours suivants d’annecy pas sur que je pourrai faire bcp de velo, pas sur d’avoir acces a un velo. Peut être seulement une fois ou deux. Donc peut etre mieux de bien charger le velo en Espagne et a Annecy on compensera en course a pied.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je reste jusqu’au dimanche 9 donc dispo pour pedaler vendredi 7 et samedi 8. Surtout prévois que les 10 jours suivants d’annecy pas sur que je pourrai faire bcp de velo, pas sur d’avoir acces a un velo. Peut être seulement une fois ou deux. Donc peut etre mieux de bien charger le velo en Espagne et a Annecy on compensera en course a pied.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":341,"offset":340}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":341,"offset":340}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":341,"offset":340}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T19:01:28.000Z","edited":false},"attachments":[],"isMention":false}',1785956488448);
